text:
    .dialog-trigger {
      position: absolute;
      width: 100px;
      height: 100px;
      padding: 0;
      border: 0;
    }

    dialog {
      position: absolute;
      padding: 0;
      border: none;
      margin: 0;
      background: #ccc;
    }
  </style>
</head>
<body>
  <div id="dialog-container">
    <button class="dialog-trigger"></button>
  </div>
  <dialog
    is="positioned-dialog"
    margin="12"
    trigger-selector=".dialog-trigger"
    container-id="dialog-container"
  ></dialog>
